#### Variation 1: Okta-Based Authorization for External Users (Recommended for Members/Providers)

**Best For**: Member portals (Gainwell Go™), provider portals (Provider+™), third-party partner integrations

**Characteristics:**
- Okta Identity Cloud as authorization server with custom authorization server configuration
- Member/provider self-service registration and password management
- Authorization Code Flow with PKCE for mobile apps and SPAs
- Refresh token rotation for enhanced security
- Custom consent screens with Gainwell branding
- SMART on FHIR scope support for healthcare apps

**Benefits**: Purpose-built for external user identity at scale, excellent developer experience, comprehensive OAuth 2.0 compliance, strong security defaults

**Configuration Example:**

```javascript
// React Native mobile app with Okta OAuth + PKCE
import { authorize, refresh, revoke } from 'react-native-app-auth';

const config = {
  issuer: 'https://gainwell.okta.com/oauth2/default',
  clientId: 'gainwell-go-mobile-prod',
  redirectUrl: 'com.gainwell.go://oauth/callback',
  scopes: ['openid', 'profile', 'email', 'claims:read', 'prescriptions:read', 'offline_access'],
  usePKCE: true, // Proof Key for Code Exchange
  serviceConfiguration: {
    authorizationEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/authorize',
    tokenEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/token',
    revocationEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/revoke'
  }
};

// Initiate authorization flow
async function loginUser() {
  try {
    const authResult = await authorize(config);

    // Store tokens securely
    await SecureStore.setItemAsync('access_token', authResult.accessToken);
    await SecureStore.setItemAsync('refresh_token', authResult.refreshToken);
    await SecureStore.setItemAsync('id_token', authResult.idToken);

    console.log('Login successful:', {
      accessTokenExpiration: authResult.accessTokenExpirationDate,
      scopes: authResult.scopes
    });

    return authResult;
  } catch (error) {
    console.error('OAuth authorization failed:', error);
    throw error;
  }
}

// Automatically refresh expired access token
async function callApiWithAutoRefresh(endpoint) {
  let accessToken = await SecureStore.getItemAsync('access_token');

  try {
    const response = await fetch(`https://api.gainwell.com${endpoint}`, {
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Accept': 'application/json'
      }
    });

    if (response.status === 401) {
      // Access token expired - refresh it
      const refreshToken = await SecureStore.getItemAsync('refresh_token');
      const refreshResult = await refresh(config, { refreshToken });

      // Update stored tokens
      await SecureStore.setItemAsync('access_token', refreshResult.accessToken);
      await SecureStore.setItemAsync('refresh_token', refreshResult.refreshToken);

      // Retry request with new token
      return fetch(`https://api.gainwell.com${endpoint}`, {
        headers: {
          'Authorization': `Bearer ${refreshResult.accessToken}`,
          'Accept': 'application/json'
        }
      });
    }

    return response;
  } catch (error) {
    console.error('API call failed:', error);
    throw error;
  }
}

// Logout and revoke tokens
async function logoutUser() {
  const refreshToken = await SecureStore.getItemAsync('refresh_token');

  if (refreshToken) {
    await revoke(config, { tokenToRevoke: refreshToken, sendClientId: true });
  }

  // Clear stored tokens
  await SecureStore.deleteItemAsync('access_token');
  await SecureStore.deleteItemAsync('refresh_token');
  await SecureStore.deleteItemAsync('id_token');
}
```

