#### Variation 3: SMART on FHIR for Healthcare Interoperability (CMS Compliance)

**Best For**: FHIR APIs requiring CMS Interoperability Rule compliance, EHR integrations, clinical decision support apps

**Characteristics:**
- OAuth 2.0 with healthcare-specific SMART scopes (patient/*.read, user/*.write)
- Launch context for EHR integration (patient context, encounter context)
- Asymmetric client authentication (JWKS for confidential clients)
- Support for backend services (bulk data export)
- Conformance to HL7 SMART App Launch Framework

**Benefits**: CMS regulatory compliance, healthcare industry standard, EHR vendor interoperability, clinical context sharing

**Configuration Example:**

```yaml
# SMART on FHIR Authorization Server Configuration
smart_on_fhir_config:
  capabilities:
    - launch-standalone      # Standalone launch (user selects patient)
    - launch-ehr             # EHR-integrated launch (EHR provides patient context)
    - client-public          # Public clients (mobile apps, SPAs)
    - client-confidential-symmetric  # Confidential clients with client secret
    - client-confidential-asymmetric # Confidential clients with JWKS
    - sso-openid-connect     # OpenID Connect for authentication
    - context-standalone-patient   # Patient context in standalone launch
    - context-ehr-patient    # Patient context from EHR launch
    - permission-patient     # Patient-level scopes
    - permission-user        # User-level scopes
    - permission-offline     # Offline access (refresh tokens)

  scopes:
    # Patient-specific scopes (SMART on FHIR)
    - patient/Patient.read         # Read patient demographics
    - patient/Claim.read           # Read patient claims
    - patient/ExplanationOfBenefit.read  # Read EOBs
    - patient/Coverage.read        # Read insurance coverage
    - patient/MedicationRequest.read     # Read prescriptions
    - patient/*.read               # Read all patient data

    # User-specific scopes (clinician/provider access)
    - user/Patient.read            # Read all patients user has access to
    - user/Claim.read              # Read all claims user has access to

    # Offline access
    - offline_access               # Refresh token for background sync

    # OpenID Connect
    - openid                       # User authentication
    - profile                      # User profile information
    - fhirUser                     # FHIR resource representing the user

  token_endpoint_auth_methods:
    - client_secret_basic          # HTTP Basic authentication
    - client_secret_post           # POST body parameters
    - private_key_jwt              # Asymmetric JWT assertion (JWKS)

  grant_types:
    - authorization_code           # Standard OAuth flow
    - refresh_token                # Token refresh
    - client_credentials           # Backend services (bulk data)

  response_types:
    - code                         # Authorization code

  code_challenge_methods:
    - S256                         # SHA-256 PKCE

# Example SMART launch parameters
launch_context:
  patient: "Patient/123456"        # Patient resource ID
  encounter: "Encounter/789"       # Current encounter (optional)
  tenant: "state-medicaid-ca"      # Multi-tenant identifier
  fhirUser: "Practitioner/456"     # Clinician identity
```

**SMART App Launch Sequence:**

```javascript
// SMART on FHIR app launch from EHR
const SMART_CONFIG = {
  clientId: 'care-coordination-app',
  scope: 'launch/patient patient/Claim.read patient/ExplanationOfBenefit.read openid profile fhirUser offline_access',
  redirectUri: 'https://carecoordination.example.com/smart/callback',
  iss: 'https://fhir.gainwell.com'  // FHIR server base URL
};

// 1. Discover SMART configuration from FHIR server
async function discoverSmartConfig() {
  const response = await fetch(`${SMART_CONFIG.iss}/.well-known/smart-configuration`);
  const smartConfig = await response.json();

  return {
    authorizationEndpoint: smartConfig.authorization_endpoint,
    tokenEndpoint: smartConfig.token_endpoint,
    capabilities: smartConfig.capabilities
  };
}

// 2. Initiate SMART launch
async function initiateSmartLaunch(launch) {
  const smartConfig = await discoverSmartConfig();

  // Generate PKCE parameters
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = await generateCodeChallenge(codeVerifier);

  // Build authorization URL with launch context
  const authUrl = new URL(smartConfig.authorizationEndpoint);
  authUrl.searchParams.set('response_type', 'code');
  authUrl.searchParams.set('client_id', SMART_CONFIG.clientId);
  authUrl.searchParams.set('redirect_uri', SMART_CONFIG.redirectUri);
  authUrl.searchParams.set('scope', SMART_CONFIG.scope);
  authUrl.searchParams.set('state', generateState());
  authUrl.searchParams.set('aud', SMART_CONFIG.iss);
  authUrl.searchParams.set('launch', launch);  // Launch context token from EHR
  authUrl.searchParams.set('code_challenge', codeChallenge);
  authUrl.searchParams.set('code_challenge_method', 'S256');

  // Redirect to authorization endpoint
  window.location.href = authUrl.toString();
}

// 3. Handle authorization callback
async function handleCallback(code, state) {
  const smartConfig = await discoverSmartConfig();

  // Exchange authorization code for tokens
  const tokenResponse = await fetch(smartConfig.tokenEndpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      code: code,
      redirect_uri: SMART_CONFIG.redirectUri,
      client_id: SMART_CONFIG.clientId,
      code_verifier: getStoredCodeVerifier()
    })
  });

  const tokens = await tokenResponse.json();

  return {
    accessToken: tokens.access_token,
    refreshToken: tokens.refresh_token,
    idToken: tokens.id_token,
    patient: tokens.patient,        // Patient ID from launch context
    fhirUser: tokens.fhirUser,      // Clinician FHIR resource URL
    scope: tokens.scope,
    expiresIn: tokens.expires_in
  };
}

// 4. Access FHIR resources with token
async function fetchPatientClaims(accessToken, patientId) {
  const response = await fetch(
    `${SMART_CONFIG.iss}/Claim?patient=${patientId}`,
    {
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Accept': 'application/fhir+json'
      }
    }
  );

  const bundle = await response.json();
  return bundle.entry.map(e => e.resource);
}
```

