#### Phase 2: Backend API OAuth Integration (Weeks 5-8)

**Week 5-6: ASP.NET Core API OAuth Implementation**

**Step 2.1: Configure JWT Bearer Authentication**

```csharp
// ASP.NET Core 8 API with OAuth 2.0 JWT Bearer authentication
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.Security.Claims;

var builder = WebApplication.CreateBuilder(args);

// Configure JWT Bearer authentication with Okta
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        // Okta authority (issuer)
        options.Authority = "https://gainwell.okta.com/oauth2/default";
        options.Audience = "https://api.gainwell.com";

        // Token validation parameters
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidIssuer = "https://gainwell.okta.com/oauth2/default",

            ValidateAudience = true,
            ValidAudience = "https://api.gainwell.com",

            ValidateLifetime = true,
            ClockSkew = TimeSpan.FromMinutes(5),  // 5-minute clock skew tolerance

            ValidateIssuerSigningKey = true,
            // Signing keys automatically fetched from JWKS endpoint

            NameClaimType = ClaimTypes.NameIdentifier,  // Map "sub" claim to Name
            RoleClaimType = "role"  // Map "role" claim to Role
        };

        // Token validation events for custom logic and logging
        options.Events = new JwtBearerEvents
        {
            OnTokenValidated = context =>
            {
                var logger = context.HttpContext.RequestServices
                    .GetRequiredService<ILogger<Program>>();

                var userId = context.Principal?.FindFirst("sub")?.Value;
                var scopes = context.Principal?.FindFirst("scp")?.Value?.Split(' ') ?? Array.Empty<string>();
                var clientId = context.Principal?.FindFirst("cid")?.Value;

                logger.LogInformation(
                    "JWT token validated. User: {UserId}, Client: {ClientId}, Scopes: {Scopes}",
                    userId, clientId, string.Join(", ", scopes)
                );

                // Store scopes in claims for later authorization checks
                if (scopes.Any())
                {
                    var identity = context.Principal?.Identity as ClaimsIdentity;
                    foreach (var scope in scopes)
                    {
                        identity?.AddClaim(new Claim("scope", scope));
                    }
                }

                return Task.CompletedTask;
            },

            OnAuthenticationFailed = context =>
            {
                var logger = context.HttpContext.RequestServices
                    .GetRequiredService<ILogger<Program>>();

                logger.LogWarning(
                    "JWT authentication failed. Reason: {Reason}, Exception: {Exception}",
                    context.Exception.Message,
                    context.Exception
                );

                // Custom error response for expired tokens
                if (context.Exception is SecurityTokenExpiredException)
                {
                    context.Response.Headers.Add("X-Token-Expired", "true");
                    context.Response.Headers.Add("WWW-Authenticate",
                        "Bearer error=\"invalid_token\", error_description=\"Token expired\"");
                }

                return Task.CompletedTask;
            },

            OnChallenge = context =>
            {
                var logger = context.HttpContext.RequestServices
                    .GetRequiredService<ILogger<Program>>();

                logger.LogWarning(
                    "Authentication challenge issued. Path: {Path}, Error: {Error}",
                    context.Request.Path,
                    context.Error
                );

                return Task.CompletedTask;
            }
        };

        // Cache JWKS keys for performance (5-minute cache)
        options.MetadataAddress = "https://gainwell.okta.com/oauth2/default/.well-known/openid-configuration";
        options.RefreshOnIssuerKeyNotFound = true;
        options.MapInboundClaims = false;  // Don't map JWT claims to legacy claim types
    });

// Configure scope-based authorization policies
builder.Services.AddAuthorization(options =>
{
    // Claims read scope policy
    options.AddPolicy("ClaimsReadScope", policy =>
    {
        policy.RequireAuthenticatedUser();
        policy.RequireClaim("scope", "claims:read");
    });

    // Claims write scope policy
    options.AddPolicy("ClaimsWriteScope", policy =>
    {
        policy.RequireAuthenticatedUser();
        policy.RequireClaim("scope", "claims:write");
    });

    // Prescriptions read scope policy
    options.AddPolicy("PrescriptionsReadScope", policy =>
    {
        policy.RequireAuthenticatedUser();
        policy.RequireClaim("scope", "prescriptions:read");
    });

    // Multiple scopes required (AND logic)
    options.AddPolicy("FullAccessScope", policy =>
    {
        policy.RequireAuthenticatedUser();
        policy.RequireClaim("scope", "claims:read", "claims:write", "prescriptions:read");
    });
});

// Add controllers
builder.Services.AddControllers();

// Add API versioning
builder.Services.AddApiVersioning(options =>
{
    options.ReportApiVersions = true;
    options.AssumeDefaultVersionWhenUnspecified = true;
    options.DefaultApiVersion = new Microsoft.AspNetCore.Mvc.ApiVersion(1, 0);
});

var app = builder.Build();

// Enable authentication middleware
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

app.Run();
```

**Step 2.2: Implement Scope-Based Authorization in Controllers**

```csharp
// Claims API controller with OAuth scope-based authorization
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

[ApiController]
[Route("api/v1/[controller]")]
[Authorize]  // All endpoints require authentication
public class ClaimsController : ControllerBase
{
    private readonly IClaimsRepository _repository;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(
        IClaimsRepository repository,
        ILogger<ClaimsController> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    /// <summary>
    /// Get claims for authenticated member (requires claims:read scope)
    /// </summary>
    [HttpGet("member/{memberId}")]
    [Authorize(Policy = "ClaimsReadScope")]
    [ProducesResponseType(typeof(List<ClaimDto>), 200)]
    [ProducesResponseType(401)]  // Unauthorized (no/invalid token)
    [ProducesResponseType(403)]  // Forbidden (insufficient scopes)
    public async Task<IActionResult> GetMemberClaims(string memberId)
    {
        // Extract user context from JWT claims
        var userId = User.FindFirst("sub")?.Value;
        var clientId = User.FindFirst("cid")?.Value;
        var scopes = User.FindAll("scope").Select(c => c.Value).ToList();

        _logger.LogInformation(
            "GetMemberClaims request. User: {UserId}, Client: {ClientId}, Member: {MemberId}, Scopes: {Scopes}",
            userId, clientId, memberId, string.Join(", ", scopes)
        );

        // Authorization check: User can only access their own claims (unless admin)
        if (userId != memberId && !User.HasClaim("role", "Admin"))
        {
            _logger.LogWarning(
                "Authorization denied. User {UserId} attempted to access member {MemberId} claims",
                userId, memberId
            );
            return Forbid();
        }

        // Retrieve claims with row-level security
        var claims = await _repository.GetClaimsByMemberIdAsync(memberId);

        _logger.LogInformation(
            "Retrieved {ClaimCount} claims for member {MemberId}",
            claims.Count, memberId
        );

        return Ok(claims);
    }

    /// <summary>
    /// Submit new claim (requires claims:write scope)
    /// </summary>
    [HttpPost]
    [Authorize(Policy = "ClaimsWriteScope")]
    [ProducesResponseType(typeof(ClaimDto), 201)]
    [ProducesResponseType(400)]  // Bad Request (validation error)
    [ProducesResponseType(401)]  // Unauthorized
    [ProducesResponseType(403)]  // Forbidden (insufficient scopes)
    public async Task<IActionResult> SubmitClaim([FromBody] CreateClaimRequest request)
    {
        var userId = User.FindFirst("sub")?.Value;
        var clientId = User.FindFirst("cid")?.Value;

        _logger.LogInformation(
            "SubmitClaim request. User: {UserId}, Client: {ClientId}, Provider: {ProviderId}",
            userId, clientId, request.ProviderId
        );

        // Business logic validation
        if (!await _repository.IsProviderAuthorizedAsync(request.ProviderId, userId))
        {
            _logger.LogWarning(
                "Authorization denied. User {UserId} not authorized for provider {ProviderId}",
                userId, request.ProviderId
            );
            return Forbid();
        }

        // Create claim
        var claim = await _repository.CreateClaimAsync(request, userId, clientId);

        _logger.LogInformation(
            "Claim created successfully. ClaimId: {ClaimId}, SubmittedBy: {UserId}",
            claim.ClaimId, userId
        );

        return CreatedAtAction(
            nameof(GetClaimById),
            new { claimId = claim.ClaimId },
            claim
        );
    }

    /// <summary>
    /// Get claim by ID (requires claims:read scope)
    /// </summary>
    [HttpGet("{claimId}")]
    [Authorize(Policy = "ClaimsReadScope")]
    [ProducesResponseType(typeof(ClaimDto), 200)]
    [ProducesResponseType(404)]  // Not Found
    [ProducesResponseType(403)]  // Forbidden
    public async Task<IActionResult> GetClaimById(string claimId)
    {
        var userId = User.FindFirst("sub")?.Value;

        var claim = await _repository.GetClaimByIdAsync(claimId);

        if (claim == null)
        {
            return NotFound();
        }

        // Authorization check: User can only access their own claims
        if (claim.MemberId != userId && !User.HasClaim("role", "Admin"))
        {
            _logger.LogWarning(
                "Authorization denied. User {UserId} attempted to access claim {ClaimId} belonging to member {MemberId}",
                userId, claimId, claim.MemberId
            );
            return Forbid();
        }

        return Ok(claim);
    }

    /// <summary>
    /// Revoke user's OAuth refresh tokens (logout)
    /// </summary>
    [HttpPost("logout")]
    [Authorize]
    [ProducesResponseType(204)]  // No Content (success)
    public async Task<IActionResult> Logout()
    {
        var userId = User.FindFirst("sub")?.Value;
        var clientId = User.FindFirst("cid")?.Value;

        // Call token revocation service to revoke all user's refresh tokens
        await RevokeUserRefreshTokensAsync(userId, clientId);

        _logger.LogInformation(
            "User logged out. Refresh tokens revoked. User: {UserId}, Client: {ClientId}",
            userId, clientId
        );

        return NoContent();
    }

    // Helper method: Revoke refresh tokens via Okta API
    private async Task RevokeUserRefreshTokensAsync(string userId, string clientId)
    {
        var oktaClient = new HttpClient();
        oktaClient.DefaultRequestHeaders.Add("Authorization", $"SSWS {Environment.GetEnvironmentVariable("OKTA_API_TOKEN")}");

        // Get all refresh tokens for user + client
        var tokensResponse = await oktaClient.GetAsync(
            $"https://gainwell.okta.com/api/v1/users/{userId}/clients/{clientId}/tokens"
        );

        if (tokensResponse.IsSuccessStatusCode)
        {
            var tokens = await tokensResponse.Content.ReadFromJsonAsync<List<OktaToken>>();

            // Revoke each refresh token
            foreach (var token in tokens?.Where(t => t.TokenType == "refresh_token") ?? Enumerable.Empty<OktaToken>())
            {
                await oktaClient.DeleteAsync(
                    $"https://gainwell.okta.com/api/v1/users/{userId}/clients/{clientId}/tokens/{token.Id}"
                );
            }
        }
    }
}

public record OktaToken(string Id, string TokenType, string Status);
```

