#### Phase 3: Mobile & Web Client Integration (Weeks 9-12)

**Week 9-10: React Native Mobile App OAuth**

**Step 3.1: Implement Authorization Code Flow with PKCE**

```typescript
// React Native mobile app OAuth implementation
import React, { useState, useEffect, createContext, useContext } from 'react';
import { authorize, refresh, revoke, AuthConfiguration, AuthorizeResult } from 'react-native-app-auth';
import * as SecureStore from 'expo-secure-store';
import { Alert } from 'react-native';

// OAuth configuration
const OAUTH_CONFIG: AuthConfiguration = {
  issuer: 'https://gainwell.okta.com/oauth2/default',
  clientId: 'gainwell-go-mobile-prod',
  redirectUrl: 'com.gainwell.go://oauth/callback',
  scopes: [
    'openid',
    'profile',
    'email',
    'offline_access',  // Request refresh token
    'claims:read',
    'prescriptions:read',
    'member:profile'
  ],
  usePKCE: true,  // Enable PKCE for mobile security
  serviceConfiguration: {
    authorizationEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/authorize',
    tokenEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/token',
    revocationEndpoint: 'https://gainwell.okta.com/oauth2/default/v1/revoke'
  }
};

// Auth context for app-wide state management
interface AuthContextType {
  isAuthenticated: boolean;
  user: UserProfile | null;
  login: () => Promise<void>;
  logout: () => Promise<void>;
  callApi: (endpoint: string, options?: RequestInit) => Promise<Response>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState<UserProfile | null>(null);

  // Check for existing session on app start
  useEffect(() => {
    checkExistingSession();
  }, []);

  // Check if user has valid tokens
  async function checkExistingSession() {
    try {
      const accessToken = await SecureStore.getItemAsync('access_token');
      const refreshToken = await SecureStore.getItemAsync('refresh_token');
      const idToken = await SecureStore.getItemAsync('id_token');

      if (accessToken && refreshToken) {
        // Decode ID token to get user profile
        const profile = decodeIdToken(idToken);
        setUser(profile);
        setIsAuthenticated(true);

        // Check if access token is expired and refresh if needed
        const expirationStr = await SecureStore.getItemAsync('access_token_expiration');
        const expiration = new Date(expirationStr || 0);

        if (expiration < new Date()) {
          // Token expired, refresh it
          await refreshAccessToken();
        }
      }
    } catch (error) {
      console.error('Error checking existing session:', error);
      // Clear potentially corrupted tokens
      await clearTokens();
    }
  }

  // Login with OAuth Authorization Code Flow + PKCE
  async function login() {
    try {
      const authResult: AuthorizeResult = await authorize(OAUTH_CONFIG);

      // Store tokens securely
      await SecureStore.setItemAsync('access_token', authResult.accessToken);
      await SecureStore.setItemAsync('refresh_token', authResult.refreshToken);
      await SecureStore.setItemAsync('id_token', authResult.idToken);
      await SecureStore.setItemAsync('access_token_expiration', authResult.accessTokenExpirationDate);

      // Decode and store user profile
      const profile = decodeIdToken(authResult.idToken);
      setUser(profile);
      setIsAuthenticated(true);

      console.log('Login successful:', {
        userId: profile.sub,
        email: profile.email,
        scopes: authResult.scopes,
        expiresAt: authResult.accessTokenExpirationDate
      });
    } catch (error) {
      console.error('OAuth login failed:', error);
      Alert.alert(
        'Login Failed',
        'Unable to authenticate. Please try again.',
        [{ text: 'OK' }]
      );
      throw error;
    }
  }

  // Logout and revoke tokens
  async function logout() {
    try {
      const refreshToken = await SecureStore.getItemAsync('refresh_token');

      // Revoke refresh token on server
      if (refreshToken) {
        await revoke(OAUTH_CONFIG, {
          tokenToRevoke: refreshToken,
          sendClientId: true
        });
      }

      // Clear local tokens
      await clearTokens();
      setUser(null);
      setIsAuthenticated(false);

      console.log('Logout successful');
    } catch (error) {
      console.error('Logout failed:', error);
      // Clear tokens anyway on error
      await clearTokens();
      setUser(null);
      setIsAuthenticated(false);
    }
  }

  // API call with automatic token refresh
  async function callApi(endpoint: string, options: RequestInit = {}): Promise<Response> {
    let accessToken = await SecureStore.getItemAsync('access_token');

    // Make API request
    let response = await fetch(`https://api.gainwell.com${endpoint}`, {
      ...options,
      headers: {
        ...options.headers,
        'Authorization': `Bearer ${accessToken}`,
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      }
    });

    // If token expired (401), refresh and retry
    if (response.status === 401) {
      console.log('Access token expired, refreshing...');

      try {
        await refreshAccessToken();
        accessToken = await SecureStore.getItemAsync('access_token');

        // Retry request with new token
        response = await fetch(`https://api.gainwell.com${endpoint}`, {
          ...options,
          headers: {
            ...options.headers,
            'Authorization': `Bearer ${accessToken}`,
            'Accept': 'application/json',
            'Content-Type': 'application/json'
          }
        });
      } catch (refreshError) {
        console.error('Token refresh failed:', refreshError);
        // Force user to re-authenticate
        await logout();
        throw new Error('Session expired. Please log in again.');
      }
    }

    return response;
  }

  // Refresh access token using refresh token
  async function refreshAccessToken() {
    try {
      const refreshToken = await SecureStore.getItemAsync('refresh_token');

      if (!refreshToken) {
        throw new Error('No refresh token available');
      }

      const refreshResult = await refresh(OAUTH_CONFIG, { refreshToken });

      // Update stored tokens
      await SecureStore.setItemAsync('access_token', refreshResult.accessToken);
      await SecureStore.setItemAsync('access_token_expiration', refreshResult.accessTokenExpirationDate);

      // Refresh token rotation: Okta may issue new refresh token
      if (refreshResult.refreshToken) {
        await SecureStore.setItemAsync('refresh_token', refreshResult.refreshToken);
      }

      console.log('Access token refreshed successfully');
    } catch (error) {
      console.error('Token refresh failed:', error);
      throw error;
    }
  }

  // Helper: Clear all tokens
  async function clearTokens() {
    await SecureStore.deleteItemAsync('access_token');
    await SecureStore.deleteItemAsync('refresh_token');
    await SecureStore.deleteItemAsync('id_token');
    await SecureStore.deleteItemAsync('access_token_expiration');
  }

  // Helper: Decode ID token JWT
  function decodeIdToken(idToken: string | null): UserProfile {
    if (!idToken) return { sub: '', email: '', name: '' };

    try {
      const base64Url = idToken.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(
        atob(base64)
          .split('')
          .map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
          .join('')
      );
      return JSON.parse(jsonPayload);
    } catch (error) {
      console.error('Error decoding ID token:', error);
      return { sub: '', email: '', name: '' };
    }
  }

  return (
    <AuthContext.Provider value={{ isAuthenticated, user, login, logout, callApi }}>
      {children}
    </AuthContext.Provider>
  );
};

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
}

interface UserProfile {
  sub: string;
  email: string;
  name: string;
}

// Usage example in a screen component
export function ClaimsScreen() {
  const { callApi } = useAuth();
  const [claims, setClaims] = useState([]);

  useEffect(() => {
    loadClaims();
  }, []);

  async function loadClaims() {
    try {
      const response = await callApi('/api/v1/claims/member/me');
      const data = await response.json();
      setClaims(data);
    } catch (error) {
      console.error('Error loading claims:', error);
      Alert.alert('Error', 'Unable to load claims. Please try again.');
    }
  }

  // Render claims list...
}
