### Example 1: Gainwell Go™ Mobile App Member Authentication

**Context:**
Gainwell's flagship mobile application serves 12 million active Medicaid members across 15 states, providing access to claims history, prescription refills, provider search, and ID card downloads. The app previously used username/password authentication directly to backend APIs, creating security risks (credentials stored locally) and poor user experience (frequent re-authentication). OAuth 2.0 Authorization Code Flow with PKCE provides secure, seamless authentication with SSO across multiple Gainwell products.

**Business Requirements:**
- Members authenticate once and remain logged in for 30 days (via refresh tokens)
- App requests only necessary permissions (claims read, prescriptions read, profile)
- Members can revoke app access from account settings web portal
- Compliance with mobile app security best practices (no credential storage)
- Support biometric authentication (Face ID, Touch ID) for re-authentication

**OAuth 2.0 Implementation:**

```typescript
// Gainwell Go mobile app: OAuth 2.0 with biometric authentication
import React, { useState, useEffect } from 'react';
import { authorize, refresh } from 'react-native-app-auth';
import * as LocalAuthentication from 'expo-local-authentication';
import * as SecureStore from 'expo-secure-store';
import { Alert } from 'react-native';

const OAUTH_CONFIG = {
  issuer: 'https://gainwell.okta.com/oauth2/default',
  clientId: 'gainwell-go-mobile-prod',
  redirectUrl: 'com.gainwell.go://oauth/callback',
  scopes: ['openid', 'profile', 'email', 'offline_access', 'claims:read', 'prescriptions:read', 'member:profile'],
  usePKCE: true
};

export function LoginScreen() {
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [biometricType, setBiometricType] = useState<string | null>(null);

  useEffect(() => {
    checkBiometricAvailability();
  }, []);

  // Check if device supports biometric authentication
  async function checkBiometricAvailability() {
    const compatible = await LocalAuthentication.hasHardwareAsync();
    if (compatible) {
      const types = await LocalAuthentication.supportedAuthenticationTypesAsync();
      if (types.includes(LocalAuthentication.AuthenticationType.FACIAL_RECOGNITION)) {
        setBiometricType('Face ID');
      } else if (types.includes(LocalAuthentication.AuthenticationType.FINGERPRINT)) {
        setBiometricType('Touch ID');
      }
    }
  }

  // Login with OAuth 2.0 Authorization Code Flow + PKCE
  async function handleLogin() {
    setIsAuthenticating(true);

    try {
      // Initiate OAuth authorization (opens browser for Okta login)
      const authResult = await authorize(OAUTH_CONFIG);

      // Store tokens securely in device keychain
      await SecureStore.setItemAsync('access_token', authResult.accessToken);
      await SecureStore.setItemAsync('refresh_token', authResult.refreshToken);
      await SecureStore.setItemAsync('id_token', authResult.idToken);
      await SecureStore.setItemAsync('token_expiration', authResult.accessTokenExpirationDate);

      // Enable biometric authentication for future logins
      if (biometricType) {
        await SecureStore.setItemAsync('biometric_enabled', 'true', {
          keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY
        });
      }

      console.log('Login successful', {
        userId: authResult.idToken,
        scopes: authResult.scopes,
        expiresAt: authResult.accessTokenExpirationDate
      });

      // Navigate to home screen
      navigation.navigate('Home');
    } catch (error) {
      console.error('Login failed:', error);
      Alert.alert('Login Failed', 'Unable to authenticate. Please try again.');
    } finally {
      setIsAuthenticating(false);
    }
  }

  // Re-authenticate using biometrics (no browser redirect)
  async function handleBiometricLogin() {
    try {
      // Check if biometric is enabled
      const biometricEnabled = await SecureStore.getItemAsync('biometric_enabled');
      if (!biometricEnabled) {
        Alert.alert('Biometric Not Enabled', 'Please log in with your credentials first.');
        return;
      }

      // Prompt biometric authentication
      const result = await LocalAuthentication.authenticateAsync({
        promptMessage: `Authenticate with ${biometricType}`,
        fallbackLabel: 'Use password instead',
        cancelLabel: 'Cancel'
      });

      if (result.success) {
        // Retrieve refresh token and get new access token
        const refreshToken = await SecureStore.getItemAsync('refresh_token');

        if (refreshToken) {
          const refreshResult = await refresh(OAUTH_CONFIG, { refreshToken });

          // Update tokens
          await SecureStore.setItemAsync('access_token', refreshResult.accessToken);
          await SecureStore.setItemAsync('token_expiration', refreshResult.accessTokenExpirationDate);

          // Update refresh token if rotated
          if (refreshResult.refreshToken) {
            await SecureStore.setItemAsync('refresh_token', refreshResult.refreshToken);
          }

          console.log('Biometric authentication successful');
          navigation.navigate('Home');
        } else {
          Alert.alert('Session Expired', 'Please log in again.');
        }
      } else {
        console.log('Biometric authentication cancelled');
      }
    } catch (error) {
      console.error('Biometric authentication failed:', error);
      Alert.alert('Authentication Failed', 'Please log in with your credentials.');
    }
  }

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Gainwell Go</Text>
      <Text style={styles.subtitle}>Manage your healthcare on the go</Text>

      <TouchableOpacity
        style={styles.loginButton}
        onPress={handleLogin}
        disabled={isAuthenticating}>
        <Text style={styles.loginButtonText}>
          {isAuthenticating ? 'Authenticating...' : 'Sign In Securely'}
        </Text>
      </TouchableOpacity>

      {biometricType && (
        <TouchableOpacity
          style={styles.biometricButton}
          onPress={handleBiometricLogin}>
          <Icon name="fingerprint" size={24} color="#007AFF" />
          <Text style={styles.biometricButtonText}>
            Sign in with {biometricType}
          </Text>
        </TouchableOpacity>
      )}

      <Text style={styles.securityNote}>
        🔒 Your credentials are never stored on this device.
        Powered by industry-standard OAuth 2.0 security.
      </Text>
    </View>
  );
}
```

**API Integration (Claims History Screen):**

```typescript
// Claims history screen with automatic token refresh
export function ClaimsHistoryScreen() {
  const [claims, setClaims] = useState<Claim[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadClaims();
  }, []);

  async function loadClaims() {
    try {
      setLoading(true);
      setError(null);

      // Make API call with automatic token refresh
      const response = await callApiWithRefresh('/api/v1/claims/member/me');
      const claimsData = await response.json();

      setClaims(claimsData);
    } catch (err) {
      console.error('Error loading claims:', err);
      setError('Unable to load claims. Please try again.');
    } finally {
      setLoading(false);
    }
  }

  // Helper: API call with automatic token refresh on 401
  async function callApiWithRefresh(endpoint: string, options: RequestInit = {}): Promise<Response> {
    let accessToken = await SecureStore.getItemAsync('access_token');

    // Initial API request
    let response = await fetch(`https://api.gainwell.com${endpoint}`, {
      ...options,
      headers: {
        ...options.headers,
        'Authorization': `Bearer ${accessToken}`,
        'Accept': 'application/json'
      }
    });

    // If 401 Unauthorized, refresh token and retry
    if (response.status === 401) {
      console.log('Access token expired, refreshing...');

      const refreshToken = await SecureStore.getItemAsync('refresh_token');
      if (!refreshToken) {
        // No refresh token, force re-login
        navigation.navigate('Login');
        throw new Error('Session expired. Please log in again.');
      }

      try {
        const refreshResult = await refresh(OAUTH_CONFIG, { refreshToken });

        // Update stored tokens
        await SecureStore.setItemAsync('access_token', refreshResult.accessToken);
        await SecureStore.setItemAsync('token_expiration', refreshResult.accessTokenExpirationDate);
        if (refreshResult.refreshToken) {
          await SecureStore.setItemAsync('refresh_token', refreshResult.refreshToken);
        }

        // Retry original request with new token
        accessToken = refreshResult.accessToken;
        response = await fetch(`https://api.gainwell.com${endpoint}`, {
          ...options,
          headers: {
            ...options.headers,
            'Authorization': `Bearer ${accessToken}`,
            'Accept': 'application/json'
          }
        });
      } catch (refreshError) {
        console.error('Token refresh failed:', refreshError);
        navigation.navigate('Login');
        throw new Error('Session expired. Please log in again.');
      }
    }

    return response;
  }

  // Render claims list...
}
```

**Outcomes:**
- **Security**: Zero credentials stored on device; tokens stored in iOS Keychain/Android Keystore (encrypted at rest)
- **User Experience**: Members remain logged in for 30 days; biometric re-authentication takes < 2 seconds (vs. 45-second username/password flow)
- **Compliance**: HIPAA-compliant authentication; audit trail shows unique user identifier for all data access
- **Metrics**: 92% of members enable biometric login; 78% reduction in password reset requests; 4.3/5 app store rating (up from 3.1 with password auth)

