### Example 2: Provider Portal Single Sign-On (SSO) with Azure AD

**Context:**
Gainwell operates 5 provider-facing web portals (claims submission, prior authorization, eligibility verification, payment history, secure messaging) across 50 states. Providers previously maintained separate usernames/passwords for each portal, leading to 15,000+ monthly password resets and 67% password reuse (security risk). OAuth 2.0 Authorization Code Flow with Azure AD provides seamless SSO across all portals, integrating with providers' existing Office 365/Azure AD tenants.

**Business Requirements:**
- Single login provides access to all authorized provider portals (SSO)
- Support Azure AD B2B (federated authentication with provider organizations)
- Providers authenticate with their organization's Azure AD (no separate credentials)
- Role-based access control: office managers see billing, clinicians see clinical data
- Session timeout after 60 minutes of inactivity

**OAuth 2.0 Implementation:**

```typescript
// Provider portal: React SPA with Azure AD OAuth 2.0
import React, { useEffect, useState } from 'react';
import { PublicClientApplication, InteractionType } from '@azure/msal-browser';
import { MsalProvider, useMsal, useIsAuthenticated } from '@azure/msal-react';

// Azure AD OAuth configuration
const msalConfig = {
  auth: {
    clientId: 'provider-portal-client-id',
    authority: 'https://login.microsoftonline.com/gainwell.onmicrosoft.com',
    redirectUri: 'https://providers.gainwell.com/oauth/callback',
    postLogoutRedirectUri: 'https://providers.gainwell.com'
  },
  cache: {
    cacheLocation: 'sessionStorage',  // Store tokens in session storage (cleared on browser close)
    storeAuthStateInCookie: false
  }
};

// OAuth scopes for provider portal APIs
const loginRequest = {
  scopes: [
    'api://provider-api/claims.submit',
    'api://provider-api/authorization.request',
    'api://provider-api/eligibility.verify',
    'api://provider-api/payments.view'
  ]
};

const msalInstance = new PublicClientApplication(msalConfig);

// App wrapper with MSAL provider
export function App() {
  return (
    <MsalProvider instance={msalInstance}>
      <ProviderPortalApp />
    </MsalProvider>
  );
}

// Main provider portal application
function ProviderPortalApp() {
  const { instance, accounts } = useMsal();
  const isAuthenticated = useIsAuthenticated();
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  useEffect(() => {
    if (isAuthenticated && accounts.length > 0) {
      loadUserProfile();
    }
  }, [isAuthenticated, accounts]);

  // Load user profile from ID token
  async function loadUserProfile() {
    const account = accounts[0];

    // Extract user information from Azure AD token claims
    const profile: UserProfile = {
      userId: account.localAccountId,
      name: account.name || '',
      email: account.username,
      organization: account.tenantId,
      roles: account.idTokenClaims?.roles || [],
      npi: account.idTokenClaims?.extension_NPI || ''  // Custom claim: National Provider Identifier
    };

    setUserProfile(profile);

    console.log('User authenticated:', {
      name: profile.name,
      organization: profile.organization,
      roles: profile.roles
    });
  }

  // Login with Azure AD
  async function handleLogin() {
    try {
      await instance.loginRedirect(loginRequest);
    } catch (error) {
      console.error('Login failed:', error);
    }
  }

  // Logout and clear session
  async function handleLogout() {
    try {
      await instance.logoutRedirect({
        postLogoutRedirectUri: 'https://providers.gainwell.com'
      });
    } catch (error) {
      console.error('Logout failed:', error);
    }
  }

  if (!isAuthenticated) {
    return (
      <div className="login-page">
        <h1>Gainwell Provider Portal</h1>
        <p>Sign in with your organization's Azure AD account</p>
        <button onClick={handleLogin} className="login-button">
          Sign In with Microsoft
        </button>
      </div>
    );
  }

  return (
    <div className="provider-portal">
      <header>
        <h1>Gainwell Provider Portal</h1>
        <div className="user-info">
          <span>{userProfile?.name}</span>
          <span>{userProfile?.organization}</span>
          <button onClick={handleLogout}>Sign Out</button>
        </div>
      </header>

      <nav>
        {userProfile?.roles.includes('ClaimsSubmitter') && (
          <a href="/claims">Submit Claims</a>
        )}
        {userProfile?.roles.includes('AuthorizationManager') && (
          <a href="/prior-auth">Prior Authorization</a>
        )}
        {userProfile?.roles.includes('EligibilityVerifier') && (
          <a href="/eligibility">Verify Eligibility</a>
        )}
        {userProfile?.roles.includes('BillingManager') && (
          <a href="/payments">Payment History</a>
        )}
      </nav>

      <main>
        {/* Portal content */}
      </main>
    </div>
  );
}

// API service with automatic token acquisition
export class ProviderApiService {
  private msalInstance: PublicClientApplication;

  constructor(msalInstance: PublicClientApplication) {
    this.msalInstance = msalInstance;
  }

  // Submit claim with OAuth token
  async submitClaim(claim: ClaimSubmission): Promise<ClaimResponse> {
    const token = await this.getAccessToken(['api://provider-api/claims.submit']);

    const response = await fetch('https://api.gainwell.com/api/v1/provider/claims', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(claim)
    });

    if (!response.ok) {
      throw new Error(`Claim submission failed: ${response.statusText}`);
    }

    return await response.json();
  }

  // Get eligibility with OAuth token
  async verifyEligibility(memberId: string, serviceDate: string): Promise<EligibilityResponse> {
    const token = await this.getAccessToken(['api://provider-api/eligibility.verify']);

    const response = await fetch(
      `https://api.gainwell.com/api/v1/provider/eligibility?memberId=${memberId}&serviceDate=${serviceDate}`,
      {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json'
        }
      }
    );

    if (!response.ok) {
      throw new Error(`Eligibility verification failed: ${response.statusText}`);
    }

    return await response.json();
  }

  // Helper: Acquire access token silently (with automatic refresh)
  private async getAccessToken(scopes: string[]): Promise<string> {
    const accounts = this.msalInstance.getAllAccounts();

    if (accounts.length === 0) {
      throw new Error('No authenticated user');
    }

    try {
      // Attempt silent token acquisition (uses cached token or refresh token)
      const response = await this.msalInstance.acquireTokenSilent({
        scopes,
        account: accounts[0]
      });

      return response.accessToken;
    } catch (error) {
      console.error('Silent token acquisition failed:', error);

      // If silent acquisition fails, trigger interactive login
      const response = await this.msalInstance.acquireTokenPopup({ scopes });
      return response.accessToken;
    }
  }
}

interface UserProfile {
  userId: string;
  name: string;
  email: string;
  organization: string;
  roles: string[];
  npi: string;
}
```

**Azure AD B2B Federation Configuration:**

```bash
#!/bin/bash
# Azure AD B2B: Invite external provider organization

az login
az account set --subscription "Gainwell-Provider-Portal"

# Invite external organization (e.g., Mayo Clinic) for SSO
az ad b2b-invitation create \

  --invited-user-email-address "admin@mayoclinic.org" \
  --invited-user-display-name "Mayo Clinic Admin" \
  --send-invitation-message true \
  --invitation-redirect-url "https://providers.gainwell.com/onboarding" \
  --invited-user-message-info "Welcome to Gainwell Provider Portal. You can now sign in with your Mayo Clinic credentials."

# Grant provider organization access to claims submission scope
az ad app permission add \

  --id "provider-portal-client-id" \
  --api "api://provider-api" \
  --api-permissions "claims.submit=Scope"
```

**Outcomes:**
- **User Experience**: Reduced password resets via SSO; single login across multiple Gainwell products; streamlined provider authentication workflow
- **Security**: Eliminated password reuse; centralized access control through Azure AD; MFA enforced by provider organizations
- **Operational Efficiency**: Reduced provider helpdesk calls related to authentication; IT teams manage access through Azure AD groups
- **Adoption**: States progressively adopting Azure AD SSO; provider organizations federated via Azure AD B2B

