### Example 3: Third-Party Care Coordination App (SMART on FHIR)

**Context:**
A third-party care coordination company (CareConnect) develops a mobile app helping case managers coordinate care for Medicaid members with complex conditions. The app needs access to member claims, medications, and care plans via Gainwell's FHIR APIs. CMS Interoperability Rule requires OAuth 2.0 with SMART on FHIR scopes, user consent, and standards-compliant authorization flows.

**Business Requirements:**
- Members authorize CareConnect app to access their healthcare data
- App requests specific FHIR resources with SMART scopes (patient/Claim.read, patient/MedicationRequest.read)
- Members can view and revoke third-party app access from Gainwell member portal
- Compliance with CMS Interoperability Rule (45 CFR 170.315(g)(10))
- EHR launch context support (app launched from Gainwell member portal)

**OAuth 2.0 SMART on FHIR Implementation:**

```yaml
# SMART on FHIR Configuration Discovery (.well-known/smart-configuration)
{
  "issuer": "https://auth.gainwell.com",
  "authorization_endpoint": "https://auth.gainwell.com/oauth2/authorize",
  "token_endpoint": "https://auth.gainwell.com/oauth2/token",
  "token_endpoint_auth_methods_supported": ["client_secret_basic", "private_key_jwt"],
  "registration_endpoint": "https://developers.gainwell.com/oauth2/register",
  "scopes_supported": [
    "openid", "fhirUser", "launch", "launch/patient",
    "patient/Claim.read", "patient/MedicationRequest.read", "patient/CarePlan.read",
    "patient/Condition.read", "patient/Observation.read", "patient/Patient.read",
    "user/Claim.read", "user/MedicationRequest.read", "user/CarePlan.read"
  ],
  "response_types_supported": ["code"],
  "grant_types_supported": ["authorization_code", "refresh_token"],
  "code_challenge_methods_supported": ["S256"],
  "capabilities": [
    "launch-ehr",
    "launch-standalone",
    "client-public",
    "client-confidential-symmetric",
    "sso-openid-connect",
    "context-ehr-patient",
    "context-standalone-patient",
    "permission-patient",
    "permission-user"
  ]
}
```

**CareConnect App: SMART Launch Sequence**

```javascript
// CareConnect mobile app: SMART on FHIR OAuth implementation
import { OAuth2Client } from 'smart-on-fhir-client';
import AsyncStorage from '@react-native-async-storage/async-storage';

// SMART on FHIR OAuth client configuration
const SMART_CONFIG = {
  iss: 'https://fhir.gainwell.com',  // FHIR server issuer
  redirectUri: 'careconnect://oauth/callback',
  clientId: 'careconnect-app',
  scope: 'openid fhirUser launch/patient patient/Claim.read patient/MedicationRequest.read patient/CarePlan.read offline_access'
};

export class CareConnectAuthService {
  private client: OAuth2Client | null = null;

  // Step 1: Discover SMART configuration from FHIR server
  async discoverSmartConfiguration() {
    try {
      const response = await fetch(`${SMART_CONFIG.iss}/.well-known/smart-configuration`);
      const config = await response.json();

      console.log('SMART configuration discovered:', {
        authorizationEndpoint: config.authorization_endpoint,
        tokenEndpoint: config.token_endpoint,
        supportedScopes: config.scopes_supported
      });

      return config;
    } catch (error) {
      console.error('SMART configuration discovery failed:', error);
      throw error;
    }
  }

  // Step 2: Initiate standalone launch (user-initiated from app)
  async launchStandalone() {
    try {
      // Discover SMART configuration
      const smartConfig = await this.discoverSmartConfiguration();

      // Generate PKCE code verifier and challenge
      const codeVerifier = generateCodeVerifier();
      const codeChallenge = await generateCodeChallenge(codeVerifier);

      // Store code verifier for token exchange
      await AsyncStorage.setItem('code_verifier', codeVerifier);

      // Build authorization URL with SMART parameters
      const authParams = new URLSearchParams({
        response_type: 'code',
        client_id: SMART_CONFIG.clientId,
        redirect_uri: SMART_CONFIG.redirectUri,
        scope: SMART_CONFIG.scope,
        state: generateRandomState(),
        aud: SMART_CONFIG.iss,  // SMART: FHIR server URL as audience
        code_challenge: codeChallenge,
        code_challenge_method: 'S256'
      });

      const authorizationUrl = `${smartConfig.authorization_endpoint}?${authParams.toString()}`;

      // Open browser for user authentication and consent
      const authResult = await openBrowserForAuth(authorizationUrl, SMART_CONFIG.redirectUri);

      if (authResult.error) {
        throw new Error(`Authorization failed: ${authResult.error_description}`);
      }

      // Step 3: Exchange authorization code for tokens
      const tokenResult = await this.exchangeCodeForTokens(
        smartConfig.token_endpoint,
        authResult.code,
        codeVerifier
      );

      // Step 4: Decode ID token to get FHIR user context
      const fhirUser = decodeFhirUser(tokenResult.id_token);
      const patientId = tokenResult.patient;  // SMART: Patient ID in token response

      console.log('SMART launch successful:', {
        fhirUser,
        patientId,
        scopes: tokenResult.scope
      });

      // Store tokens and context
      await this.storeSmartSession({
        accessToken: tokenResult.access_token,
        refreshToken: tokenResult.refresh_token,
        fhirUser,
        patientId,
        fhirServerUrl: SMART_CONFIG.iss
      });

      return { fhirUser, patientId };
    } catch (error) {
      console.error('SMART standalone launch failed:', error);
      throw error;
    }
  }

  // Step 3: Exchange authorization code for access token
  async exchangeCodeForTokens(tokenEndpoint: string, code: string, codeVerifier: string) {
    try {
      const response = await fetch(tokenEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded'
        },
        body: new URLSearchParams({
          grant_type: 'authorization_code',
          code,
          redirect_uri: SMART_CONFIG.redirectUri,
          client_id: SMART_CONFIG.clientId,
          code_verifier: codeVerifier
        }).toString()
      });

      if (!response.ok) {
        throw new Error(`Token exchange failed: ${response.statusText}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Token exchange failed:', error);
      throw error;
    }
  }

  // Access FHIR resources with OAuth token
  async getFhirResource(resourceType: string, patientId: string) {
    const session = await this.getSmartSession();

    if (!session) {
      throw new Error('No active SMART session');
    }

    // FHIR API request with OAuth token
    const response = await fetch(
      `${session.fhirServerUrl}/${resourceType}?patient=${patientId}`,
      {
        headers: {
          'Authorization': `Bearer ${session.accessToken}`,
          'Accept': 'application/fhir+json'
        }
      }
    );

    // Handle token expiration
    if (response.status === 401) {
      console.log('Access token expired, refreshing...');
      await this.refreshSmartSession();

      // Retry with new token
      return await this.getFhirResource(resourceType, patientId);
    }

    if (!response.ok) {
      throw new Error(`FHIR request failed: ${response.statusText}`);
    }

    return await response.json();
  }

  // Refresh SMART session using refresh token
  async refreshSmartSession() {
    const session = await this.getSmartSession();
    const smartConfig = await this.discoverSmartConfiguration();

    if (!session?.refreshToken) {
      throw new Error('No refresh token available');
    }

    const response = await fetch(smartConfig.token_endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: session.refreshToken,
        client_id: SMART_CONFIG.clientId
      }).toString()
    });

    if (!response.ok) {
      throw new Error('Token refresh failed');
    }

    const tokenResult = await response.json();

    // Update session with new tokens
    await this.storeSmartSession({
      ...session,
      accessToken: tokenResult.access_token,
      refreshToken: tokenResult.refresh_token || session.refreshToken
    });
  }

  // Store SMART session
  private async storeSmartSession(session: SmartSession) {
    await AsyncStorage.setItem('smart_session', JSON.stringify(session));
  }

  // Retrieve SMART session
  private async getSmartSession(): Promise<SmartSession | null> {
    const sessionJson = await AsyncStorage.getItem('smart_session');
    return sessionJson ? JSON.parse(sessionJson) : null;
  }
}

interface SmartSession {
  accessToken: string;
  refreshToken?: string;
  fhirUser: string;
  patientId: string;
  fhirServerUrl: string;
}

// Usage: Load member claims via FHIR API
async function loadMemberClaims(patientId: string) {
  const authService = new CareConnectAuthService();

  try {
    // FHIR Claim resource with patient search parameter
    const claimsBundle = await authService.getFhirResource('Claim', patientId);

    console.log(`Loaded ${claimsBundle.total} claims for patient ${patientId}`);

    // Process FHIR claims
    const claims = claimsBundle.entry.map((entry: any) => ({
      claimId: entry.resource.id,
      status: entry.resource.status,
      type: entry.resource.type.coding[0].display,
      created: entry.resource.created,
      provider: entry.resource.provider.display,
      total: entry.resource.total?.value
    }));

    return claims;
  } catch (error) {
    console.error('Error loading claims:', error);
    throw error;
  }
}
```

**Member Consent Management (Gainwell Member Portal):**

```typescript
// Member portal: View and revoke third-party app authorizations
export function ThirdPartyAppsScreen() {
  const [authorizedApps, setAuthorizedApps] = useState<AuthorizedApp[]>([]);

  useEffect(() => {
    loadAuthorizedApps();
  }, []);

  // Load apps authorized by member
  async function loadAuthorizedApps() {
    const response = await fetch('https://api.gainwell.com/api/v1/member/authorized-apps', {
      headers: {
        'Authorization': `Bearer ${accessToken}`
      }
    });

    const apps = await response.json();
    setAuthorizedApps(apps);
  }

  // Revoke third-party app access
  async function revokeAppAccess(appId: string) {
    const confirmed = confirm('Revoke access for this app? It will no longer be able to access your healthcare data.');

    if (!confirmed) return;

    try {
      await fetch(`https://api.gainwell.com/api/v1/member/authorized-apps/${appId}/revoke`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${accessToken}`
        }
      });

      // Refresh list
      await loadAuthorizedApps();

      alert('App access revoked successfully');
    } catch (error) {
      console.error('Revocation failed:', error);
      alert('Unable to revoke access. Please try again.');
    }
  }

  return (
    <div className="authorized-apps">
      <h2>Authorized Apps</h2>
      <p>These apps have access to your healthcare data. You can revoke access at any time.</p>

      {authorizedApps.length === 0 && (
        <p className="no-apps">You haven't authorized any apps yet.</p>
      )}

      {authorizedApps.map(app => (
        <div key={app.id} className="app-card">
          <img src={app.logo} alt={app.name} className="app-logo" />
          <div className="app-info">
            <h3>{app.name}</h3>
            <p className="app-description">{app.description}</p>
            <p className="app-permissions">
              <strong>Access:</strong> {app.scopes.join(', ')}
            </p>
            <p className="app-authorized-date">
              Authorized: {new Date(app.authorizedAt).toLocaleDateString()}
            </p>
          </div>
          <button
            onClick={() => revokeAppAccess(app.id)}
            className="revoke-button">
            Revoke Access
          </button>
        </div>
      ))}
    </div>
  );
}

interface AuthorizedApp {
  id: string;
  name: string;
  description: string;
  logo: string;
  scopes: string[];
  authorizedAt: string;
}
```

